﻿"use client";

import {
  type PointerEvent as ReactPointerEvent,
  useEffect,
  useRef,
  useState,
} from "react";
import "./heat-map.css";

/* ══ Heat word ════════════════════════════════════════════
   A big word in flat, dull grey — until the hand comes. Around
   the cursor the word turns into a heat map of its own shape:
   deep navy in the middle of every stroke, through blue, cyan,
   yellow, orange and red, to a pink rim. Right under the pointer
   the heat opens up and the strokes thin, like something melting;
   leave and it fades back to grey. Press it and the next shape
   melts in.

   ── A FIELD, THEN A PALETTE ─────────────────────────────
   The word is drawn once, blurred, into a grey field: bright in
   the thick of a stroke, fading at its edge. The cursor adds a
   soft round of heat to that field. Every pixel's brightness is
   then looked up in a 256-entry table of colours. Two strokes
   close together overlap in the field, so they fuse where the
   heat pools — that is the liquid, and nothing animates it but
   the field.

   ── THE BLUR IS A SHADOW ────────────────────────────────
   ctx.filter is not in every Safari, shadowBlur is. The word is
   drawn far off the canvas with its shadow thrown back on, so
   only the blurred shadow lands. */

const W = 300;
const H = 170;
/* one word, always: its curves and its straight stems both melt well */
const word = "INTERACT";
const WORD_LINES = ["INTE", "RACT"] as const;

const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));

/* the word is Inter at its bold, the site's own face, so it is
   already on the page and never fetched */
const FACE = { family: "Inter", weight: 700 };

/* ── or a shape, instead of a word ─────────────────────────
   The heat reads any shape, and the ones that look most liquid
   are where strokes meet or nearly touch: bars crossing at a
   centre, dots close enough to run together. Each takes a seed,
   so a press deals a new arrangement of the same kind. */
export const SHAPES = [
  "Dots",
  "Asterisk",
  "Word",
  "Rosette",
  "Rings",
  "Clover",
] as const;
export type HeatMapShape = (typeof SHAPES)[number];

/* Three vector shapes adapted from Studio's Custom Desktop pack (256x256 viewBox) */
const VECTOR_SHAPES: Record<string, string> = {
  Rosette:
    "M 128 0 C 147.68 0 164.04 14.213 167.377 32.934 C 182.974 22.055 204.594 23.574 218.51 37.49 C 232.426 51.406 233.944 73.025 223.066 88.622 C 241.787 91.96 256 108.32 256 128 C 256 147.68 241.787 164.04 223.065 167.377 C 233.944 182.974 232.426 204.594 218.51 218.51 C 204.594 232.426 182.974 233.944 167.377 223.065 C 164.04 241.787 147.68 256 128 256 C 108.32 256 91.959 241.787 88.622 223.065 C 73.025 233.944 51.406 232.426 37.49 218.51 C 23.574 204.594 22.055 182.974 32.934 167.377 C 14.213 164.04 0 147.68 0 128 C 0 108.32 14.213 91.96 32.934 88.622 C 22.056 73.025 23.574 51.406 37.49 37.49 C 51.406 23.574 73.025 22.055 88.622 32.934 C 91.96 14.213 108.32 0 128 0 Z",
  Rings:
    "M 128 0 C 198.692 0 256 57.308 256 128 C 256 198.692 198.692 256 128 256 C 57.308 256 0 198.692 0 128 C 0 57.308 57.308 0 128 0 Z M 128 32 C 74.98 32 32 74.98 32 128 C 32 181.019 74.98 224 128 224 C 181.019 224 224 181.019 224 128 C 224 74.98 181.019 32 128 32 Z M 128 56 C 167.765 56 200 88.236 200 128 C 200 167.765 167.765 200 128 200 C 88.236 200 56 167.765 56 128 C 56 88.236 88.236 56 128 56 Z M 128 88 C 105.909 88 88 105.909 88 128 C 88 150.091 105.909 168 128 168 C 150.091 168 168 150.091 168 128 C 168 105.909 150.091 88 128 88 Z M 128 112 C 136.837 112 144 119.163 144 128 C 144 136.837 136.837 144 128 144 C 119.163 144 112 136.837 112 128 C 112 119.163 119.163 112 128 112 Z",
  Clover:
    "M 192 0 C 227.346 0 256 28.654 256 64 C 256 99.346 227.346 128 192 128 C 227.346 128 256 156.654 256 192 C 256 227.346 227.346 256 192 256 C 156.654 256 128 227.346 128 192 C 128 227.346 99.346 256 64 256 C 28.654 256 0 227.346 0 192 C 0 156.654 28.654 128 64 128 C 28.654 128 0 99.346 0 64 C 0 28.654 28.654 0 64 0 C 99.346 0 128 28.654 128 64 C 128 28.654 156.654 0 192 0 Z M 128 100 C 112.536 100 100 112.536 100 128 C 100 143.464 112.536 156 128 156 C 143.464 156 156 143.464 156 128 C 156 112.536 143.464 100 128 100 Z",
};
const VECTOR_PATH_CACHE = new Map<string, Path2D>();
function vectorPath(name: string): Path2D | undefined {
  const raw = VECTOR_SHAPES[name];
  if (!raw) return undefined;
  let cached = VECTOR_PATH_CACHE.get(name);
  if (!cached) {
    cached = new Path2D(raw);
    VECTOR_PATH_CACHE.set(name, cached);
  }
  return cached;
}

function rng(seed: number) {
  let t = seed * 9301 + 49297;
  return () => {
    t = (t * 9301 + 49297) % 233280;
    return t / 233280;
  };
}

/* a thick line through a list of points */
function line(g: CanvasRenderingContext2D, pts: [number, number][]) {
  g.beginPath();
  pts.forEach(([x, y], i) => {
    if (i) g.lineTo(x, y);
    else g.moveTo(x, y);
  });
  g.stroke();
}

/* where the hand is, in the field's pixels, and how present it is */
type Hand = { x: number; y: number; on: number; area: number };

function drawShape(
  g: CanvasRenderingContext2D,
  shape: string,
  w: number,
  h: number,
  r: number,
  seed: number,
  hand?: Hand,
) {
  const rand = rng(seed);
  const cx = w / 2,
    cy = h / 2;
  g.lineCap = "round";
  g.lineJoin = "round";
  if (shape === "Dots") {
    /* a loose grid, near enough that neighbours run together. The
       dots under the hand swell, on a gaussian, so the ones nearest
       grow into each other and fuse while the far ones keep their
       size — and the rand() calls stay in the same order, so the
       arrangement never shifts while they do */
    const cols = 7,
      rows = 3;
    const reach = 62 * r * (hand?.area ?? 1);
    for (let j = 0; j < rows; j++) {
      for (let i = 0; i < cols; i++) {
        const x = cx + (i - (cols - 1) / 2) * 38 * r + (rand() - 0.5) * 8 * r;
        const y = cy + (j - (rows - 1) / 2) * 38 * r + (rand() - 0.5) * 8 * r;
        let rad = (9 + rand() * 7) * r;
        if (hand && hand.on > 0.002) {
          const d2 = ((x - hand.x) ** 2 + (y - hand.y) ** 2) / (reach * reach);
          rad *= 1 + 0.75 * hand.on * Math.exp(-d2);
        }
        g.beginPath();
        g.arc(x, y, rad, 0, Math.PI * 2);
        g.fill();
      }
    }
  } else if (shape === "Asterisk") {
    /* fat bars crossing, every one of them through the centre */
    g.lineWidth = 16 * r;
    const n = 3 + Math.floor(rand() * 2),
      turn = rand() * Math.PI;
    for (let i = 0; i < n; i++) {
      const a = turn + (i / n) * Math.PI;
      const c = Math.cos(a) * 66 * r,
        sn = Math.sin(a) * 66 * r;
      line(g, [
        [cx - c, cy - sn],
        [cx + c, cy + sn],
      ]);
    }
  } else {
    const p = vectorPath(shape);
    if (p) {
      const size = 128 * r;
      const sc = size / 256;
      g.save();
      g.translate(cx - size / 2, cy - size / 2);
      g.scale(sc, sc);
      g.fill(p, "evenodd");
      g.restore();
    }
  }
}

/* the face is on the page already, but may not have arrived by
   the first frame — waited for, or the first word is the fallback */
async function ensure() {
  try {
    await document.fonts?.load(`${FACE.weight} 100px "${FACE.family}"`);
  } catch {
    /* drawn in the fallback, which is still a word */
  }
}

/* the palettes, rim (0) to core (1); below the floor it is the card.
   Neon is the heat camera: a pink rim through red, yellow and
   cyan to a navy core. The others keep its shape — a light rim, a
   dark core, a bright band between — in other colours. */
type Stops = [number, [number, number, number]][];
export const PALETTES: Record<string, Stops> = {
  Neon: [
    [0.0, [255, 150, 225]],
    [0.1, [255, 90, 190]],
    [0.2, [255, 50, 60]],
    [0.32, [255, 150, 40]],
    [0.42, [255, 228, 100]],
    [0.54, [120, 215, 255]],
    [0.68, [40, 120, 245]],
    [0.84, [12, 44, 150]],
    [1.0, [6, 18, 80]],
  ],
  Fire: [
    [0.0, [255, 238, 180]],
    [0.16, [255, 200, 80]],
    [0.34, [255, 130, 30]],
    [0.52, [228, 58, 28]],
    [0.72, [150, 18, 44]],
    [0.88, [74, 6, 42]],
    [1.0, [30, 2, 24]],
  ],
  Sea: [
    [0.0, [210, 255, 225]],
    [0.16, [110, 245, 175]],
    [0.34, [40, 215, 200]],
    [0.52, [40, 150, 235]],
    [0.72, [80, 70, 205]],
    [0.88, [60, 20, 130]],
    [1.0, [24, 8, 60]],
  ],
  Pop: [
    [0.0, [255, 225, 240]],
    [0.16, [255, 160, 210]],
    [0.34, [245, 110, 190]],
    [0.52, [180, 110, 255]],
    [0.72, [100, 150, 255]],
    [0.88, [40, 70, 190]],
    [1.0, [20, 24, 100]],
  ],
};
export type HeatMapColors = "Neon" | "Fire" | "Sea" | "Pop";
const FLOOR = 34;

function table(STOPS: Stops) {
  const t = new Uint8ClampedArray(256 * 4);
  for (let i = 0; i < 256; i++) {
    if (i < FLOOR) {
      /* under the floor: nothing, so the card shows through */
      t[i * 4 + 3] = 0;
      continue;
    }
    const u = (i - FLOOR) / (255 - FLOOR);
    let k = 0;
    while (k < STOPS.length - 2 && u > STOPS[k + 1][0]) k++;
    const [u0, c0] = STOPS[k];
    const [u1, c1] = STOPS[k + 1];
    const f = clamp((u - u0) / (u1 - u0), 0, 1);
    for (let c = 0; c < 3; c++) t[i * 4 + c] = c0[c] + (c1[c] - c0[c]) * f;
    /* the rim fades in over the first stretch, so the pink is a
       glow at the edge rather than a hard line */
    t[i * 4 + 3] = 255 * clamp((i - FLOOR) / 26, 0, 1);
  }
  return t;
}
/* one table per palette, made the first time it is asked for */
const LUTS = new Map<string, Uint8ClampedArray>();
function lut(name: string) {
  let t = LUTS.get(name);
  if (!t) {
    t = table(PALETTES[name] ?? PALETTES.Neon);
    LUTS.set(name, t);
  }
  return t;
}

/* ── and at rest, just grey ────────────────────────────────
   The word sits on the card as a flat, dull grey — solid where
   the heat would be, soft at the edge — and the heat map is only
   ever shown where the hand is. GREY_A is the grey's alpha per
   brightness: the letter's body at full, a short soft edge. */
const GREY = [150, 150, 154];
const GREY_A = new Uint8ClampedArray(256);
for (let i = 0; i < 256; i++) GREY_A[i] = 255 * clamp((i - 70) / 45, 0, 1);

export interface HeatMapProps {
  /* how much heat the cursor brings, 0..100 */
  heat?: number;
  /* how soft the letters are, 0..100 */
  soft?: number;
  /* how big the patch under the hand is, 0..100 */
  area?: number;
  /* which heat map the hand reveals */
  colors?: HeatMapColors | string;
  /* the shape it starts on; a press steps to the next */
  shape?: HeatMapShape | string;
  /** Pause the canvas spring and cursor sweep in place */
  paused?: boolean;
  /** Incrementing this counter triggers a synthetic pointer sweep across the shape */
  replaySignal?: number;
  className?: string;
}

export function HeatMap({
  heat = 60,
  soft = 50,
  area = 50,
  colors = "Neon",
  shape: start = "Clover",
  paused = false,
  replaySignal = 0,
  className,
}: HeatMapProps = {}) {
  const pausedRef = useRef(paused);
  pausedRef.current = paused;
  const prevReplayRef = useRef(replaySignal);
  const [seed, setSeed] = useState(() => Math.floor(Math.random() * 1000));
  const [shape, setShape] = useState(start);
  /* the knob moving is a new start, whatever the presses did */
  useEffect(() => setShape(start), [start]);
  const shown = useRef<HTMLCanvasElement>(null);
  const st = useRef({
    base: null as HTMLCanvasElement | null,
    work: null as HTMLCanvasElement | null,
    px: 0.5,
    py: 0.5,
    tx: 0.5,
    ty: 0.5,
    power: 0,
    want: 0,
    grow: 0,
    raf: 0,
    ratio: 1,
    /* the dots were last drawn swollen, and owe one redraw at rest */
    swollen: false,
  });
  const sweepRafRef = useRef(0);
  const knobs = useRef({ heat, soft, area, colors });
  knobs.current = { heat, soft, area, colors };
  /* Area as a multiplier on every radius the hand has: half at 0,
     as it was at 50, half again at 100 */
  const spread = () => 0.5 + clamp(knobs.current.area, 0, 100) / 100;

  /* the word, blurred, into the base field — redrawn when the
     word or the softness changes */
  const build = () => {
    const s = st.current;
    const r = Math.min(2, window.devicePixelRatio || 1);
    s.ratio = r;
    const w = Math.round(W * r),
      h = Math.round(H * r);
    const base = s.base ?? document.createElement("canvas");
    base.width = w;
    base.height = h;
    s.base = base;
    if (!s.work) s.work = document.createElement("canvas");
    s.work.width = w;
    s.work.height = h;
    const c = shown.current;
    if (!c) return;
    c.width = w;
    c.height = h;
    field();
  };

  /* the field itself, into the base at its current size — once per
     build for a word, and every frame the hand moves for the dots,
     which change size under it */
  const field = () => {
    const s = st.current;
    const base = s.base;
    if (!base) return;
    const r = s.ratio;
    const w = base.width,
      h = base.height;
    const g = base.getContext("2d");
    if (!g) return;
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.shadowColor = "transparent";
    g.fillStyle = "#000";
    g.fillRect(0, 0, w, h);
    const blur = (6 + (clamp(knobs.current.soft, 0, 100) / 100) * 16) * r;
    const off = w * 3;
    g.shadowColor = "#fff";
    g.shadowBlur = blur;
    g.shadowOffsetX = off;
    g.fillStyle = "#fff";
    g.strokeStyle = "#fff";
    if (shape !== "Word") {
      /* drawn off the canvas so only the blurred shadow lands */
      g.save();
      g.translate(-off, 0);
      const hand = { x: s.px * w, y: s.py * h, on: s.power, area: spread() };
      drawShape(g, shape, w, h, r, seed, hand);
      drawShape(g, shape, w, h, r, seed, hand);
      g.restore();
      return;
    }
    /* as large as fits */
    let size = Math.min(150 * r, h * 0.52);
    const f = `"${FACE.family}", system-ui, sans-serif`;
    g.font = `${FACE.weight} ${size}px ${f}`;
    const maxW = Math.max(
      ...WORD_LINES.map((lineText) => g.measureText(lineText).width),
    );
    const fit = (w * 0.92) / maxW;
    size = Math.min(size, size * fit);
    g.font = `${FACE.weight} ${size}px ${f}`;
    g.textAlign = "center";
    g.textBaseline = "middle";
    const lineGap = size * 0.8;
    const startY =
      h / 2 - ((WORD_LINES.length - 1) * lineGap) / 2 + size * 0.04;
    /* twice over, so the thick of a stroke saturates */
    WORD_LINES.forEach((lineText, idx) => {
      const y = startY + idx * lineGap;
      g.fillText(lineText, w / 2 - off, y);
      g.fillText(lineText, w / 2 - off, y);
    });
  };

  /* one frame: base, plus heat at the cursor, through the palette */
  const paint = () => {
    const s = st.current;
    const c = shown.current;
    if (!c || !s.base || !s.work) return;
    const w = c.width,
      h = c.height;
    /* the dots follow the hand, so their field is redrawn with it */
    if (shape === "Dots" && (s.power > 0.002 || s.swollen)) {
      field();
      s.swollen = s.power > 0.002;
    }
    const g = s.work.getContext("2d", { willReadFrequently: true });
    const shownCtx = c.getContext("2d");
    if (!g || !shownCtx) return;
    g.globalCompositeOperation = "source-over";
    g.globalAlpha = 1;
    g.fillStyle = "#000";
    g.fillRect(0, 0, w, h);
    /* the shape grows in from nothing when it changes */
    g.globalAlpha = s.grow;
    g.drawImage(s.base, 0, 0);
    g.globalAlpha = 1;
    if (s.power > 0.002) {
      const cx = s.px * w,
        cy = s.py * h;
      const rad = (60 + (knobs.current.heat / 100) * 50) * s.ratio * spread();
      const amt = s.power * (0.35 + (knobs.current.heat / 100) * 0.55);
      /* the cursor COOLS the field: a multiply that dims it toward
         the middle of the pointer, so the navy cores open up into
         rings of blue, cyan, yellow and red and the strokes thin
         there — the letters melting under the hand */
      g.globalCompositeOperation = "multiply";
      const cool = g.createRadialGradient(cx, cy, 0, cx, cy, rad);
      const v = (k: number) => Math.round(255 * (1 - amt * k));
      cool.addColorStop(0, `rgb(${v(1)},${v(1)},${v(1)})`);
      cool.addColorStop(0.45, `rgb(${v(0.6)},${v(0.6)},${v(0.6)})`);
      cool.addColorStop(1, "rgb(255,255,255)");
      g.fillStyle = cool;
      g.fillRect(0, 0, w, h);
    }
    const src = g.getImageData(0, 0, w, h).data;
    const LUT = lut(knobs.current.colors);
    const out = shownCtx.createImageData(w, h);
    const d = out.data;
    /* the reveal: how much heat map each pixel shows, a soft disc
       around the cursor scaled by how present the hand is. Outside
       it the word is grey. */
    const cx = s.px * w,
      cy = s.py * h;
    const R = (95 + (knobs.current.heat / 100) * 55) * s.ratio * spread();
    const R2 = R * R;
    const on = s.power;
    for (let y = 0, i = 0; y < h; y++) {
      const dy2 = (y - cy) * (y - cy);
      for (let x = 0; x < w; x++, i += 4) {
        const f = src[i];
        const v = f * 4;
        let m = 0;
        if (on > 0.002) {
          const q = ((x - cx) * (x - cx) + dy2) / R2;
          if (q < 1) {
            const t = 1 - q;
            m = on * t * t * (3 - 2 * t);
          }
        }
        const ga = GREY_A[f];
        if (m <= 0) {
          d[i] = GREY[0];
          d[i + 1] = GREY[1];
          d[i + 2] = GREY[2];
          d[i + 3] = ga;
          continue;
        }
        const k = 1 - m;
        d[i] = GREY[0] * k + LUT[v] * m;
        d[i + 1] = GREY[1] * k + LUT[v + 1] * m;
        d[i + 2] = GREY[2] * k + LUT[v + 2] * m;
        d[i + 3] = ga * k + LUT[v + 3] * m;
      }
    }
    shownCtx.putImageData(out, 0, 0);
  };

  /* the loop runs only while something is moving */
  const run = () => {
    if (pausedRef.current) return;
    const s = st.current;
    if (s.raf) return;
    let prev = performance.now();
    const step = (t: number) => {
      const dt = Math.min(0.05, (t - prev) / 1000);
      prev = t;
      const k = 1 - 0.002 ** dt;
      s.px += (s.tx - s.px) * k;
      s.py += (s.ty - s.py) * k;
      s.power += (s.want - s.power) * (1 - 0.01 ** dt);
      s.grow = Math.min(1, s.grow + dt / 0.9);
      paint();
      const still =
        s.grow >= 1 &&
        Math.abs(s.want - s.power) < 0.004 &&
        Math.abs(s.tx - s.px) < 0.001 &&
        Math.abs(s.ty - s.py) < 0.001;
      if (still && s.want === 0) s.power = 0;
      s.raf = still ? 0 : requestAnimationFrame(step);
      if (still) paint();
    };
    s.raf = requestAnimationFrame(step);
  };

  const stopSweep = () => {
    if (sweepRafRef.current) {
      cancelAnimationFrame(sweepRafRef.current);
      sweepRafRef.current = 0;
    }
  };

  const hasMountedRef = useRef(false);
  const actionsRef = useRef({ build, paint, run, stopSweep });
  actionsRef.current = { build, paint, run, stopSweep };

  useEffect(() => {
    void shape;
    void seed;
    const s = st.current;
    const go = () => {
      actionsRef.current.build();
      if (!hasMountedRef.current) {
        hasMountedRef.current = true;
        s.grow = 1;
        actionsRef.current.paint();
      } else {
        s.grow = 0;
        actionsRef.current.run();
      }
    };
    /* the face first, or the first word is drawn in the fallback */
    let live = true;
    ensure().then(() => {
      if (live) go();
    });
    return () => {
      live = false;
      cancelAnimationFrame(s.raf);
      s.raf = 0;
    };
  }, [shape, seed]);

  /* softness redraws the field without replaying the melt-in */
  useEffect(() => {
    void soft;
    if (!st.current.base) return;
    actionsRef.current.build();
    actionsRef.current.paint();
  }, [soft]);

  useEffect(() => {
    if (!paused) return;
    actionsRef.current.stopSweep();
    cancelAnimationFrame(st.current.raf);
    st.current.raf = 0;
  }, [paused]);

  useEffect(() => {
    if (replaySignal <= 0) {
      if (prevReplayRef.current !== 0) {
        prevReplayRef.current = 0;
        actionsRef.current.stopSweep();
        const s = st.current;
        s.want = 0;
        actionsRef.current.run();
      }
      return;
    }
    if (prevReplayRef.current === replaySignal) return;
    prevReplayRef.current = replaySignal;
    if (pausedRef.current) return;
    actionsRef.current.stopSweep();
    const s = st.current;
    const startMs = performance.now();
    const dur = 1800;
    s.power = 0;
    s.px = 0.16;
    s.py = 0.5;
    s.tx = 0.16;
    s.ty = 0.5;
    s.want = 1;
    s.grow = 1;
    actionsRef.current.paint();
    actionsRef.current.run();
    const tick = (now: number) => {
      if (pausedRef.current) {
        sweepRafRef.current = 0;
        return;
      }
      const u = Math.min(1, (now - startMs) / dur);
      s.tx = 0.16 + 0.68 * u;
      s.ty = 0.5 + Math.sin(u * Math.PI * 2) * 0.16;
      s.want = 1;
      actionsRef.current.run();
      if (u < 1) {
        sweepRafRef.current = requestAnimationFrame(tick);
      } else {
        sweepRafRef.current = 0;
        s.want = 0;
        actionsRef.current.run();
      }
    };
    sweepRafRef.current = requestAnimationFrame(tick);
    return () => actionsRef.current.stopSweep();
  }, [replaySignal]);

  const aim = (e: ReactPointerEvent<HTMLElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    const s = st.current;
    s.tx = (e.clientX - r.left) / r.width;
    s.ty = (e.clientY - r.top) / r.height;
  };

  const advanceShape = () => {
    /* the next shape round, the dots and the asterisk dealt a
       fresh arrangement as they come back */
    const i = SHAPES.indexOf(shape as HeatMapShape);
    setSeed((n) => n + 1);
    setShape(SHAPES[(i + 1) % SHAPES.length]);
  };

  return (
    <button
      type="button"
      className={className ? `heat ${className}` : "heat"}
      style={{
        width: W,
        height: H,
        border: 0,
        padding: 0,
        background: "transparent",
      }}
      onPointerEnter={(e) => {
        stopSweep();
        aim(e);
        const s = st.current;
        s.px = s.tx;
        s.py = s.ty;
        s.want = 1;
        run();
      }}
      onPointerMove={(e) => {
        stopSweep();
        aim(e);
        st.current.want = 1;
        run();
      }}
      onPointerLeave={() => {
        stopSweep();
        st.current.want = 0;
        run();
      }}
      onClick={advanceShape}
      aria-label={
        shape === "Word"
          ? `${word}. Press for the next shape`
          : `${shape}. Press for the next shape`
      }
    >
      <canvas
        ref={shown}
        className="heat-canvas"
        style={{ width: W, height: H }}
      />
    </button>
  );
}

export default HeatMap;

